import{_ as t,o as i,c as a,ah as s}from"./chunks/framework.Cx6lfSeA.js";const k=JSON.parse('{"title":"Browser Renderer","description":"Mount $prefab wire JSON into the browser with the vanilla DOM renderer. Zero dependencies, works in any iframe or web page.","frontmatter":{"description":"Mount $prefab wire JSON into the browser with the vanilla DOM renderer. Zero dependencies, works in any iframe or web page.","head":[["link",{"rel":"canonical","href":"https://max-health-inc.github.io/prefab/guide/renderer"}],["meta",{"property":"og:url","content":"https://max-health-inc.github.io/prefab/guide/renderer"}],["meta",{"property":"og:description","content":"Mount $prefab wire JSON into the browser with the vanilla DOM renderer. Zero dependencies, works in any iframe or web page."}]]},"headers":[],"relativePath":"guide/renderer.md","filePath":"guide/renderer.md","lastUpdated":1782579855000}'),r={name:"guide/renderer.md"};function n(o,e,d,h,l,p){return i(),a("div",null,[...e[0]||(e[0]=[s(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /prefab/guide/renderer.md for this page in Markdown format</div><h1 id="browser-renderer" tabindex="-1">Browser Renderer <a class="header-anchor" href="#browser-renderer" aria-label="Permalink to &quot;Browser Renderer&quot;">​</a></h1><p>The browser renderer is how your <code>$prefab</code> UIs come alive in a real page. It is a single, self-contained script (<code>dist/renderer.min.js</code>) with <strong>zero framework dependencies</strong> — no React, no Vue, no build step. Drop it in with a <code>&lt;script&gt;</code> tag and it turns wire JSON into living DOM.</p><h2 id="the-mental-model" tabindex="-1">The mental model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The mental model&quot;">​</a></h2><p>Think of the renderer as a small machine with one job: <strong>wire JSON in, live DOM out.</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$prefab wire JSON  ──▶  renderer  ──▶  real DOM nodes</span></span></code></pre></div><p>Your server (or your LLM) describes <em>what</em> the UI should look like as plain JSON — a tree of typed nodes like <code>Column</code>, <code>H1</code>, <code>DataTable</code>. The renderer reads that tree and builds the matching HTML elements, wires up event handlers, and applies your theme. You never touch the DOM yourself.</p><p>The interesting part is what happens <em>after</em> the first paint. The renderer keeps a small <strong>reactive store</strong> alongside the DOM. When a button fires an action, or a tool call returns fresh data, the store updates and every <code>{{ ... }}</code> expression that depends on it re-evaluates automatically. The page reacts; you don&#39;t re-render by hand.</p><h2 id="how-it-fits-in-a-page" tabindex="-1">How it fits in a page <a class="header-anchor" href="#how-it-fits-in-a-page" aria-label="Permalink to &quot;How it fits in a page&quot;">​</a></h2><p>There are two ways to get a UI on screen, and which you reach for depends on whether the JSON is ready at load time.</p><p><strong>Auto-mount</strong> is the zero-code path. Stash your wire data on <code>window.__PREFAB_DATA__</code> before the script runs, and the renderer finds your <code>#root</code> (or the body) and mounts itself on <code>DOMContentLoaded</code>. Perfect for server-rendered pages that already know what to show.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;window.__PREFAB_DATA__ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$prefab&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;view&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;H1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } };&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;renderer.min.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><strong>Manual mount</strong> is for when the data arrives later — from a fetch, a tool call, or user interaction. Call <code>PrefabRenderer.mount(element, data, options)</code> yourself and you get back a <strong>render handle</strong> you can hold onto: feed it new data with <code>update()</code>, force a redraw with <code>rerender()</code>, reach into the reactive <code>store</code>, or tear everything down with <code>destroy()</code>.</p><div class="tip custom-block"><p class="custom-block-title">Always ship prefab.css</p><p>The renderer paints structure, but <code>prefab.css</code> carries the design tokens and base styles. Load it alongside the script or your components come out unstyled.</p></div><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><p>The renderer is extensible without forking it. You can teach it new node types with <code>registerComponent</code>, add new <code>{{ }}</code> filters with <code>registerPipe</code>, and inject scoped stylesheets straight from the wire format — all covered in the reference.</p><p>→ See the <a href="/prefab/reference/renderer">Renderer reference</a> for the full API: every method, option, and the render handle.</p>`,17)])])}const u=t(r,[["render",n]]);export{k as __pageData,u as default};
